<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --bg: #0d1117;
    --bg2: #161b22;
    --bg3: #1c2128;
    --border: #30363d;
    --text: #e6edf3;
    --text-muted: #8b949e;
    --accent: #00e5a0;
    --accent2: #475F91;
    --accent-dim: rgba(0,229,160,0.12);
    --radius: 8px;
    --font-mono: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  }
  body { background: var(--bg); color: var(--text); font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif; line-height: 1.6; min-height: 100vh; }
  a { color: inherit; text-decoration: none; }

  /* NAV */
  nav { position: sticky; top: 0; z-index: 100; background: rgba(13,17,23,0.92); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); }
  .nav-inner { max-width: 1280px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; gap: 0; height: 60px; }
  .nav-logo { font-size: 16px; font-weight: 700; letter-spacing: -0.3px; color: var(--text); margin-right: 40px; display: flex; align-items: center; gap: 8px; }
  .nav-logo-icon { width: 26px; height: 26px; background: linear-gradient(135deg, var(--accent), #00a8ff); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 900; color: #000; }
  .nav-links { display: flex; gap: 4px; flex: 1; }
  .nav-links a { padding: 6px 12px; border-radius: var(--radius); font-size: 14px; color: var(--text-muted); transition: color 0.15s, background 0.15s; }
  .nav-links a:hover, .nav-links a.active { color: var(--text); background: var(--bg3); }
  .nav-actions { display: flex; align-items: center; gap: 8px; }
  .nav-search { display: flex; align-items: center; gap: 8px; background: var(--bg3); border: 1px solid var(--border); border-radius: var(--radius); padding: 6px 12px; font-size: 13px; color: var(--text-muted); cursor: pointer; transition: border-color 0.15s; }
  .nav-search:hover { border-color: var(--accent2); }
  .nav-search kbd { background: var(--bg2); border: 1px solid var(--border); border-radius: 4px; padding: 1px 5px; font-size: 11px; font-family: var(--font-mono); }
  .btn-login { padding: 6px 16px; border-radius: var(--radius); background: var(--bg3); border: 1px solid var(--border); color: var(--text); font-size: 14px; cursor: pointer; transition: border-color 0.15s; }
  .btn-login:hover { border-color: var(--accent); }

  /* HERO */
  .hero { max-width: 1280px; margin: 0 auto; padding: 96px 24px 80px; }
  .hero-badge { display: inline-flex; align-items: center; gap: 6px; background: var(--accent-dim); border: 1px solid rgba(0,229,160,0.3); border-radius: 100px; padding: 4px 12px; font-size: 12px; color: var(--accent); font-weight: 500; margin-bottom: 28px; }
  .hero-badge::before { content: ''; width: 6px; height: 6px; background: var(--accent); border-radius: 50%; animation: pulse 2s infinite; }
  @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.4} }
  .hero h1 { font-size: clamp(36px, 5vw, 60px); font-weight: 800; letter-spacing: -1.5px; line-height: 1.1; margin-bottom: 24px; max-width: 780px; background: linear-gradient(135deg, #e6edf3 0%, #8b949e 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
  .hero-sub { font-size: 18px; color: var(--text-muted); max-width: 680px; line-height: 1.7; margin-bottom: 40px; }
  .hero-ctas { display: flex; flex-wrap: wrap; gap: 12px; }
  .btn-primary { display: inline-flex; align-items: center; gap: 8px; padding: 12px 24px; border-radius: var(--radius); background: var(--accent); color: #000; font-size: 14px; font-weight: 600; cursor: pointer; border: none; transition: opacity 0.15s, transform 0.1s; }
  .btn-primary:hover { opacity: 0.88; transform: translateY(-1px); }
  .btn-secondary { display: inline-flex; align-items: center; gap: 8px; padding: 12px 24px; border-radius: var(--radius); background: transparent; color: var(--text); font-size: 14px; font-weight: 500; border: 1px solid var(--border); cursor: pointer; transition: border-color 0.15s, background 0.15s; }
  .btn-secondary:hover { border-color: var(--text-muted); background: var(--bg3); }

  /* PRODUCT CARDS */
  .section { max-width: 1280px; margin: 0 auto; padding: 80px 24px; }
  .section-label { font-size: 12px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--accent); font-weight: 600; margin-bottom: 16px; }
  .section-title { font-size: clamp(24px, 3vw, 36px); font-weight: 700; letter-spacing: -0.5px; margin-bottom: 12px; }
  .section-sub { font-size: 16px; color: var(--text-muted); max-width: 600px; margin-bottom: 48px; }
  .cards-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
  .card { background: var(--bg2); border: 1px solid var(--border); border-radius: 12px; padding: 32px; transition: border-color 0.2s, transform 0.2s, box-shadow 0.2s; position: relative; overflow: hidden; }
  .card::before { content: ''; position: absolute; inset: 0; background: linear-gradient(135deg, transparent 60%, var(--accent-dim) 100%); opacity: 0; transition: opacity 0.3s; }
  .card:hover { border-color: var(--accent); transform: translateY(-2px); box-shadow: 0 8px 32px rgba(0,229,160,0.08); }
  .card:hover::before { opacity: 1; }
  .card-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 20px; margin-bottom: 20px; }
  .card-icon.green { background: rgba(0,229,160,0.15); }
  .card-icon.blue { background: rgba(71,95,145,0.3); }
  .card-icon.purple { background: rgba(139,92,246,0.15); }
  .card h3 { font-size: 20px; font-weight: 700; margin-bottom: 10px; }
  .card p { font-size: 14px; color: var(--text-muted); line-height: 1.65; margin-bottom: 24px; }
  .card-link { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; color: var(--accent); font-weight: 500; transition: gap 0.15s; }
  .card:hover .card-link { gap: 10px; }
  .divider { border: none; border-top: 1px solid var(--border); }

  /* CLI SETUP */
  .cli-section { background: var(--bg2); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
  .cli-inner { max-width: 1280px; margin: 0 auto; padding: 80px 24px; }
  .cli-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: start; }
  @media(max-width: 900px) { .cli-layout { grid-template-columns: 1fr; } }
  .cli-left h2 { font-size: clamp(22px, 2.5vw, 30px); font-weight: 700; letter-spacing: -0.5px; margin-bottom: 16px; }
  .cli-left p { font-size: 15px; color: var(--text-muted); line-height: 1.7; }

  /* ACCORDION */
  .accordion { margin-top: 0; }
  .acc-item { border: 1px solid var(--border); border-radius: var(--radius); margin-bottom: 8px; overflow: hidden; transition: border-color 0.2s; }
  .acc-item.open { border-color: var(--accent); }
  .acc-trigger { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; background: var(--bg3); cursor: pointer; border: none; color: var(--text); font-size: 15px; font-weight: 600; text-align: left; transition: background 0.15s; }
  .acc-trigger:hover { background: #1f2937; }
  .acc-icon { width: 20px; height: 20px; border-radius: 50%; background: var(--accent-dim); border: 1px solid rgba(0,229,160,0.3); display: flex; align-items: center; justify-content: center; font-size: 11px; color: var(--accent); transition: transform 0.25s; flex-shrink: 0; }
  .acc-item.open .acc-icon { transform: rotate(180deg); }
  .acc-body { display: none; padding: 0 20px 20px; background: var(--bg3); }
  .acc-item.open .acc-body { display: block; }
  .acc-steps { list-style: none; counter-reset: step; margin-bottom: 20px; }
  .acc-steps li { counter-increment: step; display: flex; align-items: flex-start; gap: 12px; margin-bottom: 12px; font-size: 14px; color: var(--text-muted); }
  .acc-steps li::before { content: counter(step); min-width: 22px; height: 22px; background: var(--accent-dim); border: 1px solid rgba(0,229,160,0.3); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; color: var(--accent); font-weight: 700; flex-shrink: 0; margin-top: 1px; }

  /* CODE TABS */
  .code-block { border-radius: var(--radius); overflow: hidden; border: 1px solid var(--border); background: #010409; }
  .code-tabs { display: flex; border-bottom: 1px solid var(--border); }
  .code-tab { padding: 8px 16px; font-size: 13px; font-family: var(--font-mono); color: var(--text-muted); cursor: pointer; border: none; background: transparent; transition: color 0.15s, background 0.15s; border-bottom: 2px solid transparent; margin-bottom: -1px; }
  .code-tab.active { color: var(--accent); border-bottom-color: var(--accent); background: rgba(0,229,160,0.05); }
  .code-tab:hover:not(.active) { color: var(--text); background: rgba(255,255,255,0.03); }
  .code-panels { padding: 16px 20px; }
  .code-panel { display: none; }
  .code-panel.active { display: block; }
  .code-panel pre { font-family: var(--font-mono); font-size: 13px; color: #79c0ff; line-height: 1.6; white-space: pre; }
  .code-panel pre .cmd { color: #a5d6ff; }
  .code-panel pre .flag { color: #79c0ff; }
  .code-panel pre .pkg { color: var(--accent); }
  .code-init { margin-top: 12px; border-radius: var(--radius); overflow: hidden; border: 1px solid var(--border); background: #010409; padding: 14px 20px; }
  .code-init pre { font-family: var(--font-mono); font-size: 13px; color: var(--accent); line-height: 1.6; }

  /* LAUNCH CTA */
  .launch-section { max-width: 1280px; margin: 0 auto; padding: 80px 24px; }
  .launch-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px; }
  .launch-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 12px; padding: 36px; }
  .launch-card h3 { font-size: 22px; font-weight: 700; margin-bottom: 12px; }
  .launch-card p { font-size: 14px; color: var(--text-muted); line-height: 1.65; margin-bottom: 28px; }

  /* COMMUNITY */
  .community-section { background: var(--bg2); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
  .community-inner { max-width: 1280px; margin: 0 auto; padding: 80px 24px; }
  .community-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; margin-top: 48px; }
  .community-card { background: var(--bg3); border: 1px solid var(--border); border-radius: var(--radius); padding: 24px; display: flex; align-items: center; justify-content: space-between; gap: 16px; transition: border-color 0.2s, transform 0.15s; cursor: pointer; }
  .community-card:hover { border-color: var(--accent2); transform: translateY(-2px); }
  .community-card-left { display: flex; align-items: center; gap: 14px; }
  .comm-icon { width: 36px; height: 36px; border-radius: 8px; background: rgba(71,95,145,0.2); border: 1px solid rgba(71,95,145,0.4); display: flex; align-items: center; justify-content: center; font-size: 16px; }
  .community-card span { font-size: 14px; font-weight: 500; }
  .comm-arrow { color: var(--text-muted); font-size: 16px; }

  /* FOOTER */
  footer { background: var(--bg); border-top: 1px solid var(--border); }
  .footer-inner { max-width: 1280px; margin: 0 auto; padding: 60px 24px 40px; }
  .footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 40px; margin-bottom: 48px; }
  .footer-col h4 { font-size: 12px; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); font-weight: 600; margin-bottom: 16px; }
  .footer-col a { display: block; font-size: 14px; color: var(--text-muted); margin-bottom: 10px; transition: color 0.15s; }
  .footer-col a:hover { color: var(--text); }
  .footer-bottom { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px; padding-top: 24px; border-top: 1px solid var(--border); }
  .footer-brand { display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--text-muted); }
  .footer-logo { width: 20px; height: 20px; background: linear-gradient(135deg, var(--accent), #00a8ff); border-radius: 4px; }
  .footer-copy { font-size: 12px; color: var(--text-muted); }

  /* RESPONSIVE */
  @media(max-width: 768px) {
    .nav-links { display: none; }
    .hero { padding: 60px 16px 48px; }
    .section { padding: 60px 16px; }
    .launch-section { padding: 60px 16px; }
    .community-inner { padding: 60px 16px; }
    .cli-inner { padding: 60px 16px; }
    .footer-inner { padding: 40px 16px 24px; }
    .nav-inner { padding: 0 16px; }
  }
  @media(max-width: 480px) {
    .hero-ctas { flex-direction: column; }
    .btn-primary, .btn-secondary { justify-content: center; }
  }
</style>
</head>
