<!-- CLI SETUP -->
<div class="cli-section">
  <div class="cli-inner">
    <div class="cli-layout">
      <div class="cli-left">
        <div class="section-label">CLI 3.0</div>
        <h2>Accelerate development with CommerceForge CLI 3.0</h2>
        <p>Initialize new apps, themes, and headless storefronts in an instant with the latest CommerceForge CLI. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>
      </div>
      <div class="cli-right">
        <div class="accordion" id="cli-accordion">

          <!-- Apps -->
          <div class="acc-item open" id="acc-apps">
            <button class="acc-trigger" onclick="toggleAcc('acc-apps')">
              Apps
              <div class="acc-icon">▾</div>
            </button>
            <div class="acc-body">
              <ol class="acc-steps">
                <li>Install CommerceForge CLI globally.</li>
                <li>Navigate to the directory where you want to create your app.</li>
                <li>Run the second command to create a new app. Your app will be added as a new subdirectory.</li>
              </ol>
              <div class="code-block">
                <div class="code-tabs">
                  <button class="code-tab active" onclick="switchTab('apps','npm')">npm</button>
                  <button class="code-tab" onclick="switchTab('apps','yarn')">yarn</button>
                  <button class="code-tab" onclick="switchTab('apps','pnpm')">pnpm</button>
                </div>
                <div class="code-panels">
                  <div class="code-panel active" id="apps-npm"><pre><span class="cmd">npm</span> <span class="flag">i -g</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                  <div class="code-panel" id="apps-yarn"><pre><span class="cmd">yarn</span> <span class="flag">global add</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                  <div class="code-panel" id="apps-pnpm"><pre><span class="cmd">pnpm</span> <span class="flag">add -g</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                </div>
              </div>
              <div class="code-init"><pre>commerceforge app init</pre></div>
            </div>
          </div>

          <!-- Themes -->
          <div class="acc-item" id="acc-themes">
            <button class="acc-trigger" onclick="toggleAcc('acc-themes')">
              Themes
              <div class="acc-icon">▾</div>
            </button>
            <div class="acc-body">
              <ol class="acc-steps">
                <li>Install CommerceForge CLI globally.</li>
                <li>Navigate to the directory where you want to create your theme.</li>
                <li>Run the second command to clone a starter theme. Your theme will be created in a new subdirectory.</li>
              </ol>
              <div class="code-block">
                <div class="code-tabs">
                  <button class="code-tab active" onclick="switchTab('themes','npm')">npm</button>
                  <button class="code-tab" onclick="switchTab('themes','yarn')">yarn</button>
                  <button class="code-tab" onclick="switchTab('themes','pnpm')">pnpm</button>
                </div>
                <div class="code-panels">
                  <div class="code-panel active" id="themes-npm"><pre><span class="cmd">npm</span> <span class="flag">i -g</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                  <div class="code-panel" id="themes-yarn"><pre><span class="cmd">yarn</span> <span class="flag">global add</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                  <div class="code-panel" id="themes-pnpm"><pre><span class="cmd">pnpm</span> <span class="flag">add -g</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                </div>
              </div>
              <div class="code-init"><pre>commerceforge theme init</pre></div>
            </div>
          </div>

          <!-- Headless -->
          <div class="acc-item" id="acc-headless">
