                  <button class="code-tab" onclick="switchTab('headless','yarn')">yarn</button>
                  <button class="code-tab" onclick="switchTab('headless','pnpm')">pnpm</button>
                </div>
                <div class="code-panels">
                  <div class="code-panel active" id="headless-npm"><pre><span class="cmd">npm</span> <span class="flag">i -g</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                  <div class="code-panel" id="headless-yarn"><pre><span class="cmd">yarn</span> <span class="flag">global add</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
                  <div class="code-panel" id="headless-pnpm"><pre><span class="cmd">pnpm</span> <span class="flag">add -g</span> <span class="pkg">@commerceforge/cli@latest</span></pre></div>
