function switchTab(section, tab) {
  // deactivate all tabs and panels in this section's code block
  const item = document.getElementById('acc-' + (section === 'apps' ? 'apps' : section === 'themes' ? 'themes' : 'headless'));
  const tabs = item.querySelectorAll('.code-tab');
  const panels = item.querySelectorAll('.code-panel');
  tabs.forEach(t => t.classList.remove('active'));
  panels.forEach(p => p.classList.remove('active'));
  // activate selected
  const selTab = Array.from(tabs).find(t => t.textContent.trim() === tab);
  const selPanel = document.getElementById(section + '-' + tab);
  if (selTab) selTab.classList.add('active');
  if (selPanel) selPanel.classList.add('active');
